def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate the solid divider, preferring the uniform line with the rarest color.
    candidates = []
    for c in range(w):
        vals = {grid[r][c] for r in range(h)}
        if len(vals) == 1:
            color = grid[0][c]
            candidates.append((sum(row.count(color) for row in grid), "col", c))
    for r in range(h):
        if len(set(grid[r])) == 1:
            color = grid[r][0]
            candidates.append((sum(row.count(color) for row in grid), "row", r))

    _, orientation, divider = min(candidates)

    if orientation == "col":
        n = min(divider, w - divider - 1)
        a = [row[divider - n:divider] for row in grid]
        b = [row[divider + 1:divider + 1 + n] for row in grid]
    else:
        n = min(divider, h - divider - 1)
        a = grid[divider - n:divider]
        b = grid[divider + 1:divider + 1 + n]

    from collections import Counter
    ca = Counter(v for row in a for v in row)
    cb = Counter(v for row in b for v in row)
    background = max(set(ca) & set(cb), key=lambda v: ca[v] + cb[v])

    return [
        [3 if a[r][c] == background and b[r][c] == background else background
         for c in range(len(a[0]))]
        for r in range(len(a))
    ]
